#!/usr/bin/env bash
python3 - <<'PYEOF'
from pathlib import Path
import re, sys
root = Path('tasks/design-shotgun/output')
files = [root / f'direction-{c}.html' for c in 'abc']
comparison = root / 'comparison.html'
errors = []
concepts = []
for path in files:
    if not path.is_file():
        errors.append(f'missing {path}')
        continue
    raw = path.read_text(errors='ignore')
    text = raw.lower()
    if len(raw) < 1800: errors.append(f'{path} is too thin')
    if '<!doctype html' not in text or '<meta name="viewport"' not in text: errors.append(f'{path} is not standalone responsive HTML')
    m = re.search(r'data-direction\s*=\s*([^\s>]+)', raw, re.I)
    if not m: errors.append(f'{path} lacks a named visual concept')
    else: concepts.append(m.group(1).strip(chr(34) + chr(39)).lower())
    for required in ['source', 'calls', 'tickets', 'slack', '15', 'trial', 'credit card']:
        if required not in text: errors.append(f'{path} misses supplied truth: {required}')
    for banned in ['trusted by', 'award-winning', '10,000 customers', 'testimonial']:
        if banned in text: errors.append(f'{path} contains unsupported proof: {banned}')
    if '@media' not in text: errors.append(f'{path} lacks responsive behavior')
if len(set(concepts)) != 3: errors.append('directions do not name three distinct concepts')
if comparison.is_file():
    c = comparison.read_text(errors='ignore').lower()
    for name in ['direction-a.html', 'direction-b.html', 'direction-c.html']:
        if name not in c: errors.append(f'comparison misses link to {name}')
    if not any(term in c for term in ['trade-off', 'tradeoff', 'trade off']): errors.append('comparison misses trade-offs')
    if 'risk' not in c or not any(term in c for term in ['best fit', 'best-fit', 'audience']): errors.append('comparison misses risks or fit guidance')
else: errors.append('missing comparison.html')
for e in errors: print('FAIL', e)
sys.exit(0 if not errors else 1)
