programmatic-seo-integration-directory.relayops-integration-pages:
#!/usr/bin/env bash
python3 - <<'PYEOF'
from pathlib import Path
import csv, json, re, sys
base = Path('tasks/programmatic-seo')
out = base / 'output'
rows = list(csv.DictReader((base / 'integrations.csv').open()))
errors, titles, descriptions = [], [], []
index = out / 'index.html'
if not index.is_file(): errors.append('missing index.html')
else:
    index_text = index.read_text(errors='ignore').lower()
    for row in rows:
        if f'pages/{row["slug"]}.html' not in index_text: errors.append(f'index misses {row["slug"]}')
for row in rows:
    path = out / 'pages' / f'{row["slug"]}.html'
    if not path.is_file():
        errors.append(f'missing {path}')
        continue
    raw = path.read_text(errors='ignore')
    text = raw.lower()
    if len(raw) < 1200: errors.append(f'{path} is too thin')
    if row['name'].lower() not in text or row['setup_minutes'] not in text or row['best_for'].lower() not in text: errors.append(f'{path} is not grounded in its source row')
    canonical = f'https://relayops.example/integrations/{row["slug"]}'
    if canonical not in raw: errors.append(f'{path} has wrong canonical URL')
    tm = re.search(r'<title>(.*?)</title>', raw, re.I | re.S)
    meta_tags = re.findall(r'<meta[^>]+>', raw, re.I)
    dm_tag = next((tag for tag in meta_tags if 'description' in tag.lower()), '')
    dm = re.search(r'content\s*=\s*([^\s>]+)', dm_tag, re.I)
    if not tm or not dm: errors.append(f'{path} lacks title or meta description')
    else:
        titles.append(re.sub(r'\s+', ' ', tm.group(1)).strip().lower())
        descriptions.append(dm.group(1).strip(chr(34) + chr(39)).lower())
    scripts = re.findall(r'<script[^>]*application/ld\+json[^>]*>(.*?)</script>', raw, re.I | re.S)
    valid_faq = False
    for script in scripts:
        try:
            data = json.loads(script)
            valid_faq = valid_faq or data.get('@type') == 'FAQPage'
        except Exception: pass
    if not valid_faq: errors.append(f'{path} lacks valid FAQPage JSON-LD')
    linked = sum(1 for other in rows if other['slug'] != row['slug'] and f'{other["slug"]}.html' in text)
    if linked < 2: errors.append(f'{path} lacks useful internal links')
    for banned in ['five-star', 'trusted by', 'customers love', 'award-winning']:
        if banned in text: errors.append(f'{path} contains unsupported proof')
if len(set(titles)) != len(rows): errors.append('page titles are not unique')
if len(set(descriptions)) != len(rows): errors.append('meta descriptions are not unique')
for e in errors: print('FAIL', e)
sys.exit(0 if not errors else 1)
PYEOF

