#!/usr/bin/env bash
python3 - <<'PYEOF'
from pathlib import Path
import re, sys
path = Path('tasks/marketing-ideas/marketing-plan.md')
raw = path.read_text(errors='ignore') if path.is_file() else ''
text = raw.lower()
errors = []
heads = list(re.finditer(r'^##\s+(?:idea\s*)?([1-5])[.):-]?\s+', raw, re.I | re.M))
if len(heads) != 5 or {m.group(1) for m in heads} != set('12345'): errors.append('plan must contain exactly five numbered idea sections')
for i, match in enumerate(heads):
    end = heads[i + 1].start() if i + 1 < len(heads) else len(raw)
    section = raw[match.start():end].lower()
    for field in ['channel', 'hook', 'why', 'cost', 'founder time', 'success metric', 'first test']:
        if field not in section: errors.append(f'idea {match.group(1)} misses {field}')
if not any(term in text for term in ['30-day sequence', '30 day sequence', '30-day plan']): errors.append('missing 30-day sequencing section')
if 'budget' not in text or '$1,000' not in raw: errors.append('missing explicit budget table and ceiling')
for constraint in ['12 hours', 'free trial']:
    if constraint not in text: errors.append(f'plan does not account for {constraint}')
for banned in ['existing audience', 'our customers say', 'guaranteed', 'industry-leading']:
    if banned in text and 'no existing audience' not in text: errors.append(f'unsupported claim detected: {banned}')
for e in errors: print('FAIL', e)
sys.exit(0 if not errors else 1)
PYEOF
